do $$begin if current_database()<>'byus_clean'or inet_server_addr()is not null then raise exception 'Fan economy tests require disposable local byus_clean';end if;end $$;
begin;
create function pg_temp.expect_fan_error(statement text,expected text)returns void language plpgsql as $$begin begin execute statement;exception when others then if position(expected in sqlerrm)>0 then return;end if;raise;end;raise exception 'Expected error %',expected;end $$;
do $$declare owner uuid:='59000000-0000-4000-8000-000000000001';other uuid:='59000000-0000-4000-8000-000000000002';creator uuid:='59000000-0000-4000-8000-000000000003';earning uuid:='59000000-0000-4000-8000-000000000004';exchange uuid:='59000000-0000-4000-8000-000000000005';vote_policy uuid:='59000000-0000-4000-8000-000000000006';project uuid:='59000000-0000-4000-8000-000000000007';key uuid:=extensions.gen_random_uuid();vote_key uuid:=extensions.gen_random_uuid();result jsonb;intent_a jsonb;intent_b jsonb;txa jsonb;txb jsonb;intent_c jsonb;intent_d jsonb;cancel_key uuid:=extensions.gen_random_uuid();entry uuid;begin
 insert into public.app_users(id,privy_user_id,verified_email)values(owner,'did:privy:fan-economy-owner','fan-economy-owner@example.test'),(other,'did:privy:fan-economy-other','fan-economy-other@example.test');
 insert into public.celebrities(id,slug,status,image_url,published_at,roles,primary_role)values(creator,'fan-economy-fixture','published','/fixture.webp',now(),'{creator}','creator');
 insert into public.celebrity_localizations(celebrity_id,locale,name,summary,image_alt)select creator,locale,'Fixture','Fixture','Fixture'from unnest(enum_range(null::public.content_locale))locale;
 if public.read_owned_mobile_fan_economy_wallet(owner,'fan-economy-fixture')#>>'{policy,status}'<>'unconfigured'then raise exception 'Unconfigured inferred rules';end if;
 if public.read_owned_mobile_fan_economy_missions(owner,'fan-economy-fixture')#>>'{policy,status}'<>'unconfigured'then raise exception 'Unconfigured missions inferred amounts';end if;
 perform pg_temp.expect_fan_error(format('select public.exchange_owned_mobile_fan_economy(%L,%L,''fan-economy-fixture'',''free_vote'',''e1'',1)',owner,key),'POLICY_UNCONFIGURED');
 insert into public.mobile_fan_economy_policies(id,celebrity_id,version,kind,rules,effective_at)values(earning,creator,'earn1','earning','{"verification":30,"comment":30}',now()-interval'1 minute'),(exchange,creator,'e1','exchange','{"free_vote":10,"free_draw":20,"maxUnits":5,"dailyLimit":5}',now()-interval'1 minute'),(vote_policy,creator,'v1','vote','{"freeEnabled":true,"paidInfluenceVerified":true,"influenceAlgorithm":"fixture-approved-independent-normalization","maxPaidInfluenceBps":2000}',now()-interval'1 minute');
 result:=public.read_owned_mobile_fan_economy_missions(owner,'fan-economy-fixture');
 if result#>>'{policy,status}'<>'configured'or not exists(select 1 from jsonb_array_elements(result->'missions')m where m->>'key'='comment'and m->>'pointAmount'='30'and m->>'status'='available')then raise exception 'Configured mission source policy not read %',result;end if;
 entry:=public.mobile_fan_economy_post(owner,creator,'fan_point',100,'test',extensions.gen_random_uuid(),earning);
 result:=public.exchange_owned_mobile_fan_economy(owner,key,'fan-economy-fixture','free_vote','e1',2);
 if result->>'pointsSpent'<>'20'or public.mobile_fan_economy_balance(owner,creator,'fan_point')<>80 or public.mobile_fan_economy_balance(owner,creator,'free_vote')<>2 then raise exception 'Atomic exchange incorrect %',result;end if;
 if (public.exchange_owned_mobile_fan_economy(owner,key,'fan-economy-fixture','free_vote','e1',2)->>'replayed')::boolean is not true then raise exception 'Replay failed';end if;
 perform pg_temp.expect_fan_error(format('select public.exchange_owned_mobile_fan_economy(%L,%L,''fan-economy-fixture'',''free_draw'',''e1'',2)',owner,key),'REQUEST_CONFLICT');
 if public.read_owned_mobile_fan_economy_request(other,key,'exchange')->>'status'<>'unknown'then raise exception 'Other owner reads result';end if;
 perform pg_temp.expect_fan_error(format('select public.exchange_owned_mobile_fan_economy(%L,%L,''fan-economy-fixture'',''free_draw'',''old'',1)',owner,extensions.gen_random_uuid()),'POLICY_CHANGED');
 perform pg_temp.expect_fan_error(format('select public.exchange_owned_mobile_fan_economy(%L,%L,''fan-economy-fixture'',''free_draw'',''e1'',4)',owner,extensions.gen_random_uuid()),'DAILY_LIMIT');
 if public.mobile_fan_economy_balance(owner,creator,'fan_point')<>80 then raise exception 'Failure mutated balance';end if;
 perform pg_temp.expect_fan_error(format('select public.mobile_fan_economy_post(%L,%L,''fan_point'',9007199254740991,''overflow'',%L,%L)',owner,creator,extensions.gen_random_uuid(),earning),'FAN_ECONOMY_INVALID');
 result:=public.exchange_owned_mobile_fan_economy(owner,extensions.gen_random_uuid(),'fan-economy-fixture','free_draw','e1',1);
 if public.get_fan_ticket_balance(owner,creator)<>1 or public.mobile_fan_economy_balance(owner,creator,'fan_point')<>60 then raise exception 'Free draw exchange failed';end if;
 result:=public.cancel_owned_mobile_fan_economy_request(owner,cancel_key,'exchange','{"celebritySlug":"fan-economy-fixture","target":"free_vote","policyVersion":"e1","units":1}');
 if result->>'status'<>'cancelled'or public.read_owned_mobile_fan_economy_request(owner,cancel_key,'exchange')->>'status'<>'cancelled'then raise exception 'Cancellation tombstone missing';end if;
 perform pg_temp.expect_fan_error(format('select public.exchange_owned_mobile_fan_economy(%L,%L,''fan-economy-fixture'',''free_vote'',''e1'',1)',owner,cancel_key),'REQUEST_CANCELLED');
 perform pg_temp.expect_fan_error(format('select public.exchange_owned_mobile_fan_economy(%L,%L,''fan-economy-fixture'',''free_vote'',''e1'',2)',owner,cancel_key),'REQUEST_CONFLICT');
 result:=public.cancel_owned_mobile_fan_economy_request(owner,key,'exchange','{"celebritySlug":"fan-economy-fixture","target":"free_vote","policyVersion":"e1","units":2}');
 if result->>'status'<>'committed'then raise exception 'Cancelled already committed exchange';end if;
 insert into public.mobile_fan_gift_projects(id,celebrity_id,title,summary,opens_at,closes_at,status,secured_budget_krw,announced_amount_krw)values(project,creator,'fixture','fixture',now()-interval'1 day',now()+interval'1 day','open',1000,500);
 result:=public.vote_owned_mobile_fan_gift(owner,project,vote_key,'v1','free',1);if public.mobile_fan_economy_balance(owner,creator,'free_vote')<>1 then raise exception 'Free vote not debited';end if;
 update public.mobile_fan_economy_policies set retired_at=clock_timestamp()where id=exchange;
 if public.exchange_owned_mobile_fan_economy(owner,key,'fan-economy-fixture','free_vote','e1',2)->>'replayed'<>'true'then raise exception 'Retired original request not replayed';end if;
 insert into public.mobile_store_sandbox_testers(app_user_id,enabled)values(owner,true);
 insert into public.mobile_vote_product_policies(store,product_id,version,vote_quantity,effective_at)values('apple','fixture-vote-5','p1',5,now()-interval'1 minute');
 intent_a:=public.create_owned_mobile_vote_intent(owner,extensions.gen_random_uuid(),'fan-economy-fixture','apple','fixture-vote-5','p1');intent_b:=public.create_owned_mobile_vote_intent(owner,extensions.gen_random_uuid(),'fan-economy-fixture','apple','fixture-vote-5','p1');
 txa:=public.apply_owned_mobile_vote_verified(owner,'apple','sandbox','fixture-txa',(intent_a->>'id')::uuid,'fixture-vote-5','KRW',1000,0,'purchased','fixture-proof-a',now());
 txb:=public.apply_owned_mobile_vote_verified(owner,'apple','sandbox','fixture-txb',(intent_b->>'id')::uuid,'fixture-vote-5','KRW',1000,0,'purchased','fixture-proof-b',now());
 perform public.apply_owned_mobile_vote_verified(owner,'apple','sandbox','fixture-txa',(intent_a->>'id')::uuid,'fixture-vote-5','KRW',1000,0,'purchased','fixture-proof-a',now());
 if public.mobile_fan_economy_balance(owner,creator,'paid_vote')<>10 then raise exception 'Duplicate purchase granted twice';end if;
 -- Spend specifically lot A, leaving B independent for the original-lot refund test.
 select transaction_id into entry from public.mobile_vote_purchase_lots where transaction_id=(select id from public.mobile_vote_transactions where external_transaction_id='fixture-txa');
 perform public.mobile_fan_economy_post(owner,creator,'paid_vote',-3,'fixture-spent-a',extensions.gen_random_uuid(),vote_policy);update public.mobile_vote_purchase_lots set spent=3 where transaction_id=entry;
 txa:=public.apply_owned_mobile_vote_verified(owner,'apple','sandbox','fixture-txa',(intent_a->>'id')::uuid,'fixture-vote-5','KRW',1000,800,'purchased','fixture-refund-a',now());
 if txa->>'heldVotes'<>'2'or txa->>'availableVotes'<>'0'or txa->>'pendingReason'<>'manual_review'then raise exception 'Spent A remaining rights not held %',txa;end if;
 if public.read_owned_mobile_fan_economy_wallet(owner,'fan-economy-fixture')#>>'{paidVotes,available}'<>'5'then raise exception 'A refund consumed B rights';end if;
 result:=public.vote_owned_mobile_fan_gift(owner,project,extensions.gen_random_uuid(),'v1','paid',1);
 if exists(select 1 from public.mobile_vote_lot_allocations where vote_id=(result->>'requestKey')::uuid and transaction_id=entry)then raise exception 'Held A spent';end if;
 if public.read_owned_mobile_fan_economy_wallet(owner,'fan-economy-fixture')#>>'{paidVotes,available}'<>'4'then raise exception 'B was not independently spendable';end if;
 txb:=public.apply_owned_mobile_vote_verified(owner,'apple','sandbox','fixture-txb',(intent_b->>'id')::uuid,'fixture-vote-5','KRW',1000,200,'purchased','fixture-refund-b',now());
 if txb->>'availableVotes'<>'3'then raise exception 'Partial B refund wrong %',txb;end if;
 intent_c:=public.create_owned_mobile_vote_intent(owner,extensions.gen_random_uuid(),'fan-economy-fixture','apple','fixture-vote-5','p1');
 result:=public.cancel_owned_mobile_fan_economy_request(owner,(intent_c->>'requestKey')::uuid,'vote_intent','{"celebritySlug":"fan-economy-fixture","store":"apple","productId":"fixture-vote-5","policyVersion":"p1"}');
 if result->>'status'<>'cancelled'then raise exception 'Unpaid intent cancellation failed';end if;
 txb:=public.apply_owned_mobile_vote_verified(owner,'apple','sandbox','fixture-late-c',(intent_c->>'id')::uuid,'fixture-vote-5','KRW',1000,0,'purchased','late-proof',now());
 if txb->>'state'<>'granted'or txb->>'availableVotes'<>'5'then raise exception 'Late legitimate native payment lost';end if;
 if public.read_owned_mobile_vote_intent(owner,(intent_c->>'requestKey')::uuid)->>'id'<>intent_c->>'id'then raise exception 'Late committed purchase hidden by cancellation';end if;
 intent_d:=public.create_owned_mobile_vote_intent(owner,extensions.gen_random_uuid(),'fan-economy-fixture','apple','fixture-vote-5','p1');
 txb:=public.apply_owned_mobile_vote_verified(owner,'apple','sandbox','fixture-pending-d',(intent_d->>'id')::uuid,'fixture-vote-5','KRW',1000,0,'pending','pending-proof',now());
 if txb->>'heldVotes'<>'0'or txb->>'finishAllowed'<>'false'or txb->>'consumeAllowed'<>'false'then raise exception 'No-lot pending projection invalid %',txb;end if;
 txb:=public.apply_owned_mobile_vote_verified(owner,'apple','sandbox','fixture-pending-d',(intent_d->>'id')::uuid,'fixture-vote-5','KRW',1000,1000,'revoked','first-revoked-proof',now());
 if txb->>'heldVotes'<>'0'or txb->>'state'<>'revoked'or txb->>'finishAllowed'<>'false'or txb->>'consumeAllowed'<>'false'then raise exception 'No-lot first-revoked projection invalid %',txb;end if;
 intent_d:=public.create_owned_mobile_vote_intent(owner,extensions.gen_random_uuid(),'fan-economy-fixture','apple','fixture-vote-5','p1');
 perform public.apply_owned_mobile_vote_verified(owner,'apple','sandbox','fixture-pending-e',(intent_d->>'id')::uuid,'fixture-vote-5','KRW',1000,0,'pending','pending-proof',now());
 perform pg_temp.expect_fan_error(format('select public.cancel_owned_mobile_fan_economy_request(%L,%L,''vote_intent'',''{"celebritySlug":"fan-economy-fixture","store":"apple","productId":"fixture-vote-5","policyVersion":"p1"}'')',owner,intent_d->>'requestKey'),'REQUEST_PENDING');
 update public.app_users set status='disabled'where id=owner;
 txb:=public.apply_mobile_vote_verified('apple','sandbox','fixture-late-c',(intent_c->>'id')::uuid,'fixture-vote-5','KRW',1000,500,'purchased','inactive-refund-proof',now(),null);
 if txb->>'pendingReason'<>'account_unavailable'or txb->>'refundedKrw'<>'500'or txb->>'heldVotes'<>'5'then raise exception 'Inactive proof branch did not record safely %',txb;end if;
 if exists(select 1 from public.mobile_vote_purchase_lots l join public.mobile_vote_transactions t on t.id=l.transaction_id where t.external_transaction_id='fixture-late-c'and l.reversed<>0)then raise exception 'Inactive callback changed rights';end if;
 update public.app_users set status='active'where id=owner;
 txb:=public.apply_mobile_vote_verified('apple','sandbox','fixture-late-c',(intent_c->>'id')::uuid,'fixture-vote-5','KRW',1000,400,'purchased','older-refund-proof',now(),null);
 if txb->>'refundedKrw'<>'500'or txb->>'availableVotes'<>'3'then raise exception 'Cumulative reverse-order refund changed %',txb;end if;
 update public.mobile_fan_economy_policies set retired_at=clock_timestamp()where id=vote_policy;
 if public.create_owned_mobile_vote_intent(owner,(intent_a->>'requestKey')::uuid,'fan-economy-fixture','apple','fixture-vote-5','p1')->>'id'<>intent_a->>'id'then raise exception 'Original inactive-policy intent lost';end if;
 perform pg_temp.expect_fan_error(format('select public.create_owned_mobile_vote_intent(%L,%L,''fan-economy-fixture'',''apple'',''fixture-vote-5'',''p1'')',owner,extensions.gen_random_uuid()),'POLICY_UNCONFIGURED');
 perform pg_temp.expect_fan_error(format('select public.apply_owned_mobile_vote_verified(%L,''apple'',''sandbox'',''fixture-txa'',%L,''fixture-vote-5'',''KRW'',1000,0,''purchased'',''proof'',now())',other,intent_a->>'id'),'ACCOUNT_MISMATCH');
 if exists(select 1 from public.mobile_store_support_ledger l join public.mobile_vote_transactions t on t.id=l.transaction_id)then raise exception 'Vote purchase contaminated legacy support';end if;
 if has_function_privilege('service_role','public.mobile_fan_economy_post(uuid,uuid,text,bigint,text,uuid,uuid)','execute')then raise exception 'Generic grant RPC exposed';end if;
 insert into public.fan_posts(app_user_id,celebrity_id,body,idempotency_key,create_request_hash,first_comment_eligible)values(owner,creator,'first fixture',extensions.gen_random_uuid(),'fixture',true);
 if public.mobile_fan_economy_balance(owner,creator,'fan_point')<>90 then raise exception 'Canonical source did not grant points';end if;
 insert into public.fan_posts(app_user_id,celebrity_id,body,idempotency_key,create_request_hash,first_comment_eligible)values(owner,creator,'second fixture',extensions.gen_random_uuid(),'fixture',true);
 if public.mobile_fan_economy_balance(owner,creator,'fan_point')<>90 then raise exception 'Canonical source granted twice';end if;
 if public.get_fan_ticket_balance(owner,creator)<>1 then raise exception 'Direct ticket producer survived cutover';end if;
 if public.award_fan_ticket_activity(owner,creator,'comment','once',false)then raise exception 'Legacy boolean helper mislabels an already awarded point';end if;
 insert into public.fan_ticket_activity_policy(celebrity_id,enabled)values(creator,true);
 result:=public.read_owned_mobile_benefit_free_ticket_missions(owner,'fan-economy-fixture');
 if result#>>'{policy,status}'<>'unconfigured'or exists(select 1 from jsonb_array_elements(result->'missions')m where m->>'ticketAmount'is not null or m->>'status'<>'unconfigured')then raise exception 'Legacy policy toggle revived direct ticket promise';end if;
 result:=public.read_owned_mobile_fan_economy_missions(owner,'fan-economy-fixture');
 if not exists(select 1 from jsonb_array_elements(result->'missions')m where m->>'key'='comment'and m->>'status'='awarded'and m->>'ledgerId'is not null)then raise exception 'Actual awarded mission receipt not projected';end if;
 raise notice 'PASS atomic exchange/replay/policy rollback/favorite isolation/free vote/paid duplicate/refund holds/source lots/retired intent/authorization/support separation';
end $$;
set constraints all immediate;
rollback;
